import { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { API_BASE, buildFileUrl } from '../config/api';
import AppIcon from '../components/AppIcon';
import { showToast, confirmDialog, promptDialog } from '../components/InstitutionalUI';
import '../CSS/ModuloEstadias.css';

const roleLabel={1:'Administrador',2:'Estudiante',4:'Profesor asesor',6:'Servicios Escolares'};
const H=()=>({Authorization:`Bearer ${localStorage.getItem('token')}`});
const dt=v=>v?new Date(v).toLocaleString('es-MX'):'—';
const d=v=>v?new Date(v).toLocaleDateString('es-MX'):'—';
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const DIAS=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
const parseHorario=(v='')=>{const [dias='',rango='']=String(v).split('|').map(x=>x.trim());const [inicio='',fin='']=rango.split('-').map(x=>x.trim());return {dias:dias?dias.split(',').map(x=>x.trim()).filter(Boolean):['Lunes','Martes','Miércoles','Jueves','Viernes'],inicio:/^\d{2}:\d{2}$/.test(inicio)?inicio:'08:00',fin:/^\d{2}:\d{2}$/.test(fin)?fin:'17:00'};};

async function api(path,options={}){
  const headers={...H(),...(options.headers||{})};
  if(options.body && !(options.body instanceof FormData)) headers['Content-Type']='application/json';
  const r=await fetch(`${API_BASE}/estadias${path}`,{...options,headers});
  const j=await r.json().catch(()=>({ok:false,mensaje:'Respuesta inválida'}));
  if(!r.ok||j.ok===false) throw new Error(j.mensaje||'No se pudo completar la operación.');
  return j;
}
async function authApi(path,options={}){
  const headers={...H(),...(options.headers||{})};
  if(options.body && !(options.body instanceof FormData)) headers['Content-Type']='application/json';
  const r=await fetch(`${API_BASE}/auth${path}`,{...options,headers});
  const j=await r.json().catch(()=>({ok:false,mensaje:'Respuesta inválida'}));
  if(!r.ok||j.ok===false) throw new Error(j.mensaje||'No se pudo completar la operación.');
  return j;
}

export default function ModuloEstadias(){
  const nav=useNavigate();
  const user=JSON.parse(localStorage.getItem('user')||'{}');
  const role=Number(user.id_rol);
  const tabs=useMemo(()=>{
    if(role===1)return [['resumen','Resumen','dashboard'],['periodos','Periodos','calendar'],['grupos-escolares','Grupos escolares','users'],['tutores','Tutores','teacher'],['grupos-estadia','Grupos de estadía','users'],['talleres','Talleres y entregas','clipboard'],['rubricas','Rúbrica y escala','file'],['expedientes','Expedientes','folder'],['seguros','Seguros','shield']];
    if(role===4)return [['mis-grupos','Mis grupos','users'],['revisiones','Avances por revisar','clipboard'],['guias','Guías','file'],['perfil','Mi perfil','user']];
    if(role===6)return [['alumnos','Alumnos','users'],['seguros','Seguro facultativo','shield'],['expedientes','Expedientes','folder'],['perfil','Mi perfil','user']];
    return [['mi-estadia','Mi estadía','briefcase'],['avances','Mis entregas','clipboard'],['seguro','Seguro facultativo','shield'],['guias','Guía','file']];
  },[role]);
  const [tab,setTab]=useState(tabs[0]?.[0]||'resumen');
  const [busy,setBusy]=useState(true);
  const [periodos,setPeriodos]=useState([]),[grupos,setGrupos]=useState([]),[talleres,setTalleres]=useState([]),[rubricas,setRubricas]=useState([]),[guias,setGuias]=useState([]);
  const [catalogos,setCatalogos]=useState({carreras:[],gruposEscolares:[],profesores:[],estudiantes:[],config:{valor_sa:8,valor_de:9,valor_au:10}});
  const [seguros,setSeguros]=useState([]),[expedientes,setExpedientes]=useState([]),[alumnos,setAlumnos]=useState([]),[misGrupos,setMisGrupos]=useState([]),[grupoDetalle,setGrupoDetalle]=useState(null),[entregasProfesor,setEntregasProfesor]=useState([]);
  const [miEstadia,setMiEstadia]=useState(null),[fechas,setFechas]=useState([]),[entregas,setEntregas]=useState([]),[contexto,setContexto]=useState(null);
  const [graficas,setGraficas]=useState({porCarrera:[],porPeriodo:[],alumnosPorGrupo:[]});
  const [adminGroupDetail,setAdminGroupDetail]=useState(null),[adminAvailable,setAdminAvailable]=useState([]),[adminAlumnoAdd,setAdminAlumnoAdd]=useState('');
  const [periodoSeleccion,setPeriodoSeleccion]=useState(null),[periodoGruposIds,setPeriodoGruposIds]=useState([]);
  const [search,setSearch]=useState(''),[carreraFiltro,setCarreraFiltro]=useState(''),[grupoFiltro,setGrupoFiltro]=useState(''),[selectedAlumno,setSelectedAlumno]=useState(null);
  const [selectedProfesorAlumno,setSelectedProfesorAlumno]=useState(null),[selectedSeguro,setSelectedSeguro]=useState(null);
  const [horarioDias,setHorarioDias]=useState(['Lunes','Martes','Miércoles','Jueves','Viernes']),[horarioInicio,setHorarioInicio]=useState('08:00'),[horarioFin,setHorarioFin]=useState('17:00');
  const [perfil,setPerfil]=useState({nombre:'',apellido:'',telefono:'',nueva_password:''});
  const [periodoForm,setPeriodoForm]=useState({nombre:'',clave:'',fecha_inicio:'',fecha_fin:'',fecha_limite_registro_empresa:'',fecha_limite_seguro:'',instrucciones:''});
  const [editPeriodo,setEditPeriodo]=useState(null);
  const [grupoEscolarForm,setGrupoEscolarForm]=useState({nombre:'',id_carrera:'',generacion:''});
  const [tallerForm,setTallerForm]=useState({id_periodo:'',nombre:'',descripcion:'',fecha_apertura:'',fecha_cierre:'',modalidad:'presencial',ubicacion:'',numero_entrega:1,id_rubrica:'',obligatorio:true});
  const [editTaller,setEditTaller]=useState(null);
  const [escala,setEscala]=useState({valor_sa:8,valor_de:9,valor_au:10});
  const [rubricaForm,setRubricaForm]=useState({nombre:'Rúbrica universal de estadía',descripcion:'',criterios:[{criterio:'Cumplimiento del entregable',peso:100}]});
  const [estadiaForm,setEstadiaForm]=useState({empresa_razon_social:'',responsable_nombre:'',responsable_cargo:'',responsable_correo:'',responsable_telefono:'',horario_laboral:'',proyecto_titulo:'',proyecto_problematica:'',proyecto_objetivo_general:'',proyecto_objetivos_especificos:'',proyecto_justificacion:'',proyecto_alcance:'',proyecto_actividades:'',proyecto_entregables:'',fecha_inicio:'',fecha_fin:''});
  const [seguroForm,setSeguroForm]=useState({numero_seguro:'',folio_pago:'',fecha_pago:'',vigencia_inicio:'',vigencia_fin:'',monto:'',archivo:null});

  const notify=(t,type='success')=>showToast(t,{type});
  const common=async()=>{const [p,g,t,r,gu]=await Promise.all([api('/periodos'),api('/grupos'),api('/talleres'),api('/rubricas'),api('/guias')]);setPeriodos(p.periodos||[]);setGrupos(g.grupos||[]);setTalleres(t.talleres||[]);setRubricas(r.rubricas||[]);setGuias(gu.guias||[]);};
  const load=async(foreground=true)=>{if(foreground)setBusy(true);try{
    await common();
    if(role===1){const [c,s,e,gr]=await Promise.all([api('/catalogos-v6'),api('/seguros'),api('/expedientes'),api('/resumen-v61')]);setCatalogos(c);setEscala(c.config||escala);setSeguros(s.seguros||[]);setExpedientes(e.expedientes||[]);setGraficas(gr.graficas||{});}
    if(role===6){const [a,s,e,p]=await Promise.all([api('/servicios/alumnos'),api('/seguros'),api('/expedientes'),authApi('/me')]);setAlumnos(a.alumnos||[]);setSeguros(s.seguros||[]);setExpedientes(e.expedientes||[]);setPerfil({...p.usuario,nueva_password:''});}
    if(role===4){const [gg,ep,p]=await Promise.all([api('/profesor/grupos'),api('/profesor/entregas'),authApi('/me')]);setMisGrupos(gg.grupos||[]);setEntregasProfesor(ep.entregas||[]);setPerfil({...p.usuario,nueva_password:''});}
    if(role===2){const [ctx,me]=await Promise.all([api('/registro/contexto'),api('/mi-estadia')]);setContexto(ctx.contexto);setMiEstadia(me.estadia);setFechas(me.fechas||[]);setEntregas(me.entregas||[]);if(me.estadia){setEstadiaForm(f=>({...f,...Object.fromEntries(Object.keys(f).map(k=>[k,me.estadia[k]??f[k]]))}));const h=parseHorario(me.estadia.horario_laboral||'');setHorarioDias(h.dias);setHorarioInicio(h.inicio);setHorarioFin(h.fin);}}
  }catch(e){notify(e.message)}finally{if(foreground)setBusy(false)}};
  useEffect(()=>{load(true)},[]);

  const savePeriodo=async(e)=>{e.preventDefault();try{await api(editPeriodo?`/periodos/${editPeriodo.id_periodo}`:'/periodos',{method:editPeriodo?'PUT':'POST',body:JSON.stringify(editPeriodo||periodoForm)});notify(editPeriodo?'Periodo actualizado.':'Periodo creado.');setEditPeriodo(null);setPeriodoForm({nombre:'',clave:'',fecha_inicio:'',fecha_fin:'',fecha_limite_registro_empresa:'',fecha_limite_seguro:'',instrucciones:''});load(false)}catch(x){notify(x.message)}};
  const saveGrupoEscolar=async(e)=>{e.preventDefault();try{await api('/grupos-escolares',{method:'POST',body:JSON.stringify(grupoEscolarForm)});notify('Grupo escolar creado.');setGrupoEscolarForm({nombre:'',id_carrera:'',generacion:''});load(false)}catch(x){notify(x.message)}};
  const toggleTutor=async(p)=>{try{await api(`/profesores/${p.id_profesor}/tutor`,{method:'PUT',body:JSON.stringify({tutor_estadia:!p.tutor_estadia,id_carrera:p.id_carrera})});load(false)}catch(x){notify(x.message)}};
  const carreraProfesor=async(p,id)=>{try{await api(`/profesores/${p.id_profesor}/tutor`,{method:'PUT',body:JSON.stringify({tutor_estadia:p.tutor_estadia,id_carrera:id||null})});load(false)}catch(x){notify(x.message)}};
  const alumnoGrupo=async(a,id)=>{try{await api(`/alumnos/${a.id_estudiante}/escolar`,{method:'PUT',body:JSON.stringify({id_grupo_escolar:id||null})});load(false)}catch(x){notify(x.message)}};
  const alumnoEstado=async(a)=>{try{await api(`/alumnos/${a.id_estudiante}/escolar`,{method:'PUT',body:JSON.stringify({estado:a.estado_usuario==='activo'?'inactivo':'activo'})});load(false)}catch(x){notify(x.message)}};
  const seleccionarGrupos=async(p)=>{try{const actuales=await api(`/periodos/${p.id_periodo}/grupos-escolares`);setPeriodoSeleccion(p);setPeriodoGruposIds((actuales.id_grupos_escolares||[]).map(Number));}catch(x){notify(x.message)}};
  const toggleGrupoPeriodo=(id)=>setPeriodoGruposIds(ids=>ids.includes(Number(id))?ids.filter(x=>x!==Number(id)):[...ids,Number(id)]);
  const guardarSeleccionPeriodo=async()=>{if(!periodoSeleccion)return;try{await api(`/periodos/${periodoSeleccion.id_periodo}/grupos-escolares`,{method:'PUT',body:JSON.stringify({id_grupos_escolares:periodoGruposIds})});notify('Grupos que salen a estadía actualizados.');setPeriodoSeleccion(null);}catch(x){notify(x.message)}};
  const generar=async(p)=>{if(!await confirmDialog({title:'Regenerar grupos de estadía',message:'Se volverán a formar los grupos de este periodo con las reglas actuales de carrera, capacidad y tutoría.',confirmText:'Regenerar grupos'}))return;try{const r=await api(`/periodos/${p.id_periodo}/generar-grupos`,{method:'POST',body:'{}'});notify(`${r.grupos_creados} grupos de estadía creados.`);load(false)}catch(x){notify(x.message)}};
  const cambiarTutorGrupo=async(g,id_profesor)=>{try{await api(`/grupos/${g.id_grupo}/tutor`,{method:'PUT',body:JSON.stringify({id_profesor})});notify('Tutor actualizado.');load(false)}catch(x){notify(x.message)}};
  const deleteGrupoEstadia=async(g)=>{if(!await confirmDialog({title:'Eliminar grupo de estadía',message:`Se eliminará ${g.nombre} y sus asignaciones si todavía no existen estadías registradas.`,confirmText:'Eliminar grupo',tone:'danger'}))return;try{await api(`/grupos/${g.id_grupo}`,{method:'DELETE'});notify('Grupo de estadía eliminado.');if(adminGroupDetail?.id_grupo===g.id_grupo){setAdminGroupDetail(null);setAdminAvailable([]);}load(false)}catch(x){notify(x.message)}};
  const saveTaller=async(e)=>{e.preventDefault();const f=editTaller||tallerForm;try{await api(editTaller?`/talleres/${editTaller.id_taller}`:'/talleres',{method:editTaller?'PUT':'POST',body:JSON.stringify(f)});notify(editTaller?'Taller actualizado.':'Taller creado.');setEditTaller(null);setTallerForm({id_periodo:'',nombre:'',descripcion:'',fecha_apertura:'',fecha_cierre:'',modalidad:'presencial',ubicacion:'',numero_entrega:1,id_rubrica:'',obligatorio:true});load(false)}catch(x){notify(x.message)}};
  const saveEscala=async()=>{try{await api('/configuracion-calificaciones',{method:'PUT',body:JSON.stringify(escala)});notify('Escala actualizada.')}catch(x){notify(x.message)}};
  const saveRubrica=async(e)=>{e.preventDefault();try{await api('/rubricas',{method:'POST',body:JSON.stringify({...rubricaForm,id_periodo:null})});notify('Rúbrica universal creada.');load(false)}catch(x){notify(x.message)}};
  const savePerfil=async(e)=>{e.preventDefault();try{await authApi('/me',{method:'PUT',body:JSON.stringify(perfil)});notify('Perfil actualizado.');setPerfil({...perfil,nueva_password:''})}catch(x){notify(x.message)}};
  const verAlumnoCompleto=async(a)=>{try{const r=await api(`/servicios/alumnos/${a.id_estudiante}`);setSelectedAlumno(r)}catch(x){notify(x.message)}};
  const abrirGrupoProfesor=async(g)=>{try{const r=await api(`/profesor/grupos/${g.id_grupo}`);setGrupoDetalle(r)}catch(x){notify(x.message)}};
  const revisar=async(e)=>{const nivel=await promptDialog({title:'Evaluar entrega',message:`${e.nombre} ${e.apellido} · ${e.titulo}`,label:'Nivel de desempeño',value:'DE',options:['SA','DE','AU'],confirmText:'Continuar'});if(!nivel)return;const observaciones=await promptDialog({title:'Retroalimentación',label:'Notas, ajustes y sugerencias',multiline:true,placeholder:'Describe de forma clara los ajustes o comentarios para el alumno.',confirmText:'Continuar'});if(observaciones===null)return;const requiere=await confirmDialog({title:'¿Requiere ajustes?',message:'Indica si el alumno debe realizar cambios adicionales a esta entrega.',confirmText:'Sí, requiere ajustes',cancelText:'No requiere ajustes'});try{await api(`/profesor/entregas/${e.id_entrega}/revision`,{method:'POST',body:JSON.stringify({nivel,observaciones,requiere_correccion:requiere})});notify('Revisión guardada.');load(false)}catch(x){notify(x.message)}};
  const habilitarMemoria=async(a)=>{if(!a.id_estadia)return notify('El alumno todavía no registra su estadía.');try{await api(`/profesor/estadias/${a.id_estadia}/memoria-final`,{method:'PUT',body:'{}'});notify('Memoria marcada como terminada. El alumno ya puede subir el PDF final.');abrirGrupoProfesor(grupoDetalle.grupo)}catch(x){notify(x.message)}};
  const saveEstadia=async(e)=>{e.preventDefault();if(!horarioDias.length)return notify('Selecciona al menos un día laboral.','warning');if(!horarioInicio||!horarioFin)return notify('Selecciona el horario de entrada y salida.','warning');const horario_laboral=`${horarioDias.join(', ')} | ${horarioInicio} - ${horarioFin}`;try{await api('/mi-estadia',{method:'POST',body:JSON.stringify({...estadiaForm,horario_laboral})});setEstadiaForm(f=>({...f,horario_laboral}));notify('Información guardada con éxito.','success');load(false)}catch(x){notify(x.message,'error')}};
  const saveSeguro=async(e)=>{e.preventDefault();const fd=new FormData();Object.entries(seguroForm).forEach(([k,v])=>{if(v!==null&&v!=='')fd.append(k,v)});try{await api('/mi-estadia/seguro',{method:'POST',body:fd});notify('Seguro enviado.');load(false)}catch(x){notify(x.message)}};
  const entregarEnlace=async(f)=>{const enlace=await promptDialog({title:'Compartir trabajo',message:'Asegúrate de haber dado permisos de editor a tu profesor antes de registrar el enlace.',label:'Enlace de Google Docs o Drive',placeholder:'https://docs.google.com/...',required:true,confirmText:'Continuar'});if(!enlace)return;const comentario=await promptDialog({title:'Nota para tu profesor',label:'Comentario opcional',multiline:true,placeholder:'Agrega contexto, dudas o indicaciones sobre esta entrega.',confirmText:'Registrar entrega'});if(comentario===null)return;try{await api(`/avances/${f.id_fecha_avance}/enlace`,{method:'POST',body:JSON.stringify({enlace_google_docs:enlace,comentario})});notify('Entrega registrada.');load(false)}catch(x){notify(x.message)}};
  const memoriaFinal=async(file)=>{if(!file)return;const fd=new FormData();fd.append('archivo',file);try{await api('/mi-estadia/memoria-final',{method:'POST',body:fd});notify('Memoria final enviada.');load(false)}catch(x){notify(x.message)}};
  const validarSeguro=async(s,estado)=>{if(!s.id_seguro)return notify('El alumno todavía no ha enviado su seguro.','warning');const observaciones=estado==='validado'?'':await promptDialog({title:estado==='rechazado'?'Rechazar seguro':'Solicitar corrección',label:'Observaciones para el alumno',multiline:true,required:true,confirmText:'Guardar decisión'});if(observaciones===null)return;try{await api(`/seguros/${s.id_seguro}`,{method:'PUT',body:JSON.stringify({estado,observaciones})});load(false)}catch(x){notify(x.message)}};
  const deletePeriodo=async(p)=>{if(!await confirmDialog({title:'Eliminar periodo',message:`Se intentará eliminar ${p.nombre}. Solo será posible si todavía no tiene estadías registradas.`,confirmText:'Eliminar periodo',tone:'danger'}))return;try{await api(`/periodos/${p.id_periodo}`,{method:'DELETE'});notify('Periodo eliminado.');load(false)}catch(x){notify(x.message)}};
  const deleteTaller=async(t)=>{if(!await confirmDialog({title:'Eliminar taller',message:`Se eliminará ${t.nombre} siempre que no tenga entregas asociadas.`,confirmText:'Eliminar taller',tone:'danger'}))return;try{await api(`/talleres/${t.id_taller}`,{method:'DELETE'});notify('Taller eliminado.');load(false)}catch(x){notify(x.message)}};
  const verGrupoAdmin=async(g)=>{
    setAdminAlumnoAdd('');
    try{const a=await api(`/grupos/${g.id_grupo}/alumnos`);setAdminGroupDetail({...g,alumnos:a.alumnos||[]});}
    catch(x){notify(x.message);return;}
    try{const d=await api(`/grupos/${g.id_grupo}/disponibles`);setAdminAvailable(d.alumnos||[]);}
    catch(x){setAdminAvailable([]);notify(`${x.message} Los alumnos ya asignados sí se muestran.`)}
  };
  const addAlumnoGrupo=async()=>{if(!adminGroupDetail||!adminAlumnoAdd)return;try{await api(`/grupos/${adminGroupDetail.id_grupo}/alumnos-manual`,{method:'POST',body:JSON.stringify({id_estudiante:adminAlumnoAdd})});notify('Alumno agregado al grupo.');await verGrupoAdmin(adminGroupDetail);load(false)}catch(x){notify(x.message)}};
  const removeAlumnoGrupo=async(a)=>{if(!await confirmDialog({title:'Retirar alumno del grupo',message:`¿Deseas retirar a ${a.nombre} ${a.apellido} de este grupo de estadía?`,confirmText:'Retirar alumno',tone:'danger'}))return;try{await api(`/grupos/${adminGroupDetail.id_grupo}/alumnos/${a.id_estudiante}`,{method:'DELETE'});notify('Alumno retirado.');await verGrupoAdmin(adminGroupDetail);load(false)}catch(x){notify(x.message)}};


  if(busy)return <div className="internship-loading">Cargando SkillMatch…</div>;
  return <div className="app internship-app"><aside className="sidebar"><div className="sidebar-logo"><div className="brand">Skill<span>Match</span></div><div className="brand-sub">Módulo de estadías</div></div><div className="nav-wrap"><div className="nav-group-label">{roleLabel[role]}</div>{tabs.map(([k,l,i])=><button key={k} className={`nav-item ${tab===k?'active':''}`} onClick={()=>setTab(k)}><span className="nav-icon"><AppIcon name={i}/></span>{l}</button>)}</div><div className="sidebar-bottom">{role!==6&&<button onClick={()=>nav(role===2?'/dashboard-estudiante':role===4?'/dashboard-profesores':'/dashboard-vinculacion')}>Volver al panel</button>}<button onClick={()=>{localStorage.clear();nav('/login')}}>Cerrar sesión</button></div></aside>
  <main className="internship-main"><header className="internship-header"><div><span className="eyebrow">SKILLMATCH · ESTADÍAS</span><h1>{tabs.find(x=>x[0]===tab)?.[1]}</h1><p>Seguimiento institucional con el mismo diseño y navegación de SkillMatch.</p></div><span className="role-pill">{roleLabel[role]}</span></header>

  {tab==='resumen'&&<section><Title e="CONTROL INSTITUCIONAL" t="Resumen de estadías"/><div className="metric-grid"><Metric l="Periodos" v={periodos.length}/><Metric l="Grupos escolares" v={catalogos.gruposEscolares?.length||0}/><Metric l="Grupos de estadía" v={grupos.length}/><Metric l="Tutores activos" v={(catalogos.profesores||[]).filter(x=>x.tutor_estadia).length}/></div><div className="chart-grid"><Panel><Title e="DISTRIBUCIÓN" t="Grupos por carrera"/><BarChart items={graficas.porCarrera||[]}/></Panel><Panel><Title e="PERIODOS" t="Grupos por periodo"/><BarChart items={graficas.porPeriodo||[]}/></Panel><Panel><Title e="CAPACIDAD" t="Alumnos por grupo de estadía"/><BarChart items={graficas.alumnosPorGrupo||[]}/></Panel></div><Info>El administrador controla periodos, grupos, tutores, talleres, entregas, rúbrica y escala de evaluación. Los profesores únicamente acompañan y evalúan a sus grupos.</Info></section>}

  {tab==='periodos'&&role===1&&<section className="two-col"><Panel><Title e="PERIODO" t={editPeriodo?'Editar periodo':'Crear periodo'}/><form className="form-grid" onSubmit={savePeriodo}>{['nombre','clave'].map(k=><Field key={k} label={k==='nombre'?'Nombre':'Clave'}><input value={(editPeriodo||periodoForm)[k]||''} onChange={e=>editPeriodo?setEditPeriodo({...editPeriodo,[k]:e.target.value}):setPeriodoForm({...periodoForm,[k]:e.target.value})} required/></Field>)}<Field label="Inicio"><input type="date" value={(editPeriodo||periodoForm).fecha_inicio?.slice?.(0,10)||''} onChange={e=>editPeriodo?setEditPeriodo({...editPeriodo,fecha_inicio:e.target.value}):setPeriodoForm({...periodoForm,fecha_inicio:e.target.value})}/></Field><Field label="Fin"><input type="date" value={(editPeriodo||periodoForm).fecha_fin?.slice?.(0,10)||''} onChange={e=>editPeriodo?setEditPeriodo({...editPeriodo,fecha_fin:e.target.value}):setPeriodoForm({...periodoForm,fecha_fin:e.target.value})}/></Field><button className="primary-btn">{editPeriodo?'Guardar cambios':'Crear periodo'}</button>{editPeriodo&&<button type="button" className="secondary-btn" onClick={()=>setEditPeriodo(null)}>Cancelar</button>}</form></Panel><Panel><Title e="PERIODOS" t="Configurados"/><div className="list-stack">{periodos.map(p=><div className="list-card" key={p.id_periodo}><div><strong>{p.nombre}</strong><span>{p.clave} · {d(p.fecha_inicio)} — {d(p.fecha_fin)}</span></div><div className="action-row"><button className="secondary-btn" onClick={()=>setEditPeriodo({...p,fecha_inicio:String(p.fecha_inicio).slice(0,10),fecha_fin:String(p.fecha_fin).slice(0,10)})}>Editar</button><button className="secondary-btn" onClick={()=>seleccionarGrupos(p)}>Grupos que salen</button><button className="primary-btn small" onClick={()=>generar(p)}>Formar grupos</button><button className="danger-btn" onClick={()=>deletePeriodo(p)}>Eliminar</button></div></div>)}</div>{periodoSeleccion&&<div className="period-group-selector"><div className="selector-head"><div><strong>Grupos que salen a estadía</strong><small>{periodoSeleccion.nombre} · selecciona únicamente los grupos que participarán en este periodo.</small></div><button className="secondary-btn small" onClick={()=>setPeriodoSeleccion(null)}>Cerrar</button></div><div className="period-group-grid">{catalogos.gruposEscolares.map(g=><label className={`period-group-option ${periodoGruposIds.includes(Number(g.id_grupo_escolar))?'selected':''}`} key={g.id_grupo_escolar}><input type="checkbox" checked={periodoGruposIds.includes(Number(g.id_grupo_escolar))} onChange={()=>toggleGrupoPeriodo(g.id_grupo_escolar)}/><span><strong>{g.nombre}</strong><small>{g.carrera} · {g.generacion||'Sin generación'} · {g.alumnos} alumnos</small></span></label>)}</div><div className="action-row selector-actions"><button className="primary-btn" onClick={guardarSeleccionPeriodo}>Guardar selección ({periodoGruposIds.length})</button></div></div>}</Panel></section>}

  {tab==='grupos-escolares'&&role===1&&<section><div className="two-col"><Panel><Title e="CATÁLOGO ESCOLAR" t="Crear grupo"/><form className="form-grid" onSubmit={saveGrupoEscolar}><Field label="Nombre"><input value={grupoEscolarForm.nombre} onChange={e=>setGrupoEscolarForm({...grupoEscolarForm,nombre:e.target.value})} placeholder="IDGS17" required/></Field><Field label="Carrera"><select value={grupoEscolarForm.id_carrera} onChange={e=>setGrupoEscolarForm({...grupoEscolarForm,id_carrera:e.target.value})} required><option value="">Selecciona…</option>{catalogos.carreras.map(c=><option value={c.id_carrera} key={c.id_carrera}>{c.nombre}</option>)}</select></Field><Field label="Generación"><input value={grupoEscolarForm.generacion} onChange={e=>setGrupoEscolarForm({...grupoEscolarForm,generacion:e.target.value})} placeholder="2024-2026"/></Field><button className="primary-btn">Crear grupo</button></form></Panel><Panel><Title e="GRUPOS" t="Grupos de la escuela"/><div className="table-wrap"><table><thead><tr><th>Grupo</th><th>Carrera</th><th>Generación</th><th>Alumnos</th></tr></thead><tbody>{catalogos.gruposEscolares.map(g=><tr key={g.id_grupo_escolar}><td><strong>{g.nombre}</strong></td><td>{g.carrera}</td><td>{g.generacion||'—'}</td><td>{g.alumnos}</td></tr>)}</tbody></table></div></Panel></div><Panel><Title e="ALUMNOS" t="Asignación de grupo escolar"/><div className="toolbar"><input placeholder="Buscar alumno o matrícula…" value={search} onChange={e=>setSearch(e.target.value)}/><select value={grupoFiltro} onChange={e=>setGrupoFiltro(e.target.value)}><option value="">Todos los grupos</option><option value="sin-grupo">Sin grupo</option>{catalogos.gruposEscolares.map(g=><option key={g.id_grupo_escolar} value={String(g.id_grupo_escolar)}>{g.nombre} · {g.carrera}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>Alumno</th><th>Carrera</th><th>Grupo</th><th>Estado</th><th></th></tr></thead><tbody>{catalogos.estudiantes.filter(a=>`${a.nombre} ${a.apellido} ${a.matricula}`.toLowerCase().includes(search.toLowerCase())&&(!grupoFiltro||(grupoFiltro==='sin-grupo'?!a.id_grupo_escolar:String(a.id_grupo_escolar)===String(grupoFiltro)))).map(a=><tr key={a.id_estudiante}><td><strong>{a.nombre} {a.apellido}</strong><small>{a.matricula}</small></td><td>{a.carrera}</td><td><select value={a.id_grupo_escolar||''} onChange={e=>alumnoGrupo(a,e.target.value)}><option value="">Sin grupo</option>{catalogos.gruposEscolares.filter(g=>norm(g.carrera)===norm(a.carrera)).map(g=><option key={g.id_grupo_escolar} value={g.id_grupo_escolar}>{g.nombre}</option>)}</select></td><td><Status v={a.estado_usuario}/></td><td><button className="secondary-btn" onClick={()=>alumnoEstado(a)}>{a.estado_usuario==='activo'?'Dar de baja':'Reactivar'}</button></td></tr>)}</tbody></table></div></Panel></section>}

  {tab==='tutores'&&role===1&&<section><Title e="PROFESORES" t="Tutores de estadía"/><Info>Solo los profesores con Tutor de estadía activado participan en la asignación automática. Cada tutor puede recibir un grupo y debe pertenecer a la misma carrera de sus alumnos.</Info><div className="table-wrap"><table><thead><tr><th>Profesor</th><th>Carrera</th><th>Tutor de estadía</th></tr></thead><tbody>{catalogos.profesores.map(p=><tr key={p.id_profesor}><td><strong>{p.nombre} {p.apellido}</strong><small>{p.correo}</small></td><td><select value={p.id_carrera||''} onChange={e=>carreraProfesor(p,e.target.value)}><option value="">Sin carrera</option>{catalogos.carreras.map(c=><option key={c.id_carrera} value={c.id_carrera}>{c.nombre}</option>)}</select></td><td><button className={`switch-btn ${p.tutor_estadia?'on':''}`} onClick={()=>toggleTutor(p)}>{p.tutor_estadia?'Sí, participa':'No participa'}</button></td></tr>)}</tbody></table></div></section>}

  {tab==='grupos-estadia'&&role===1&&<section><Title e="DISTRIBUCIÓN" t="Grupos de estadía"/><Info>La formación automática reparte alumnos de la misma carrera en grupos de 1 a 6 y asigna tutores al azar. Después puedes cambiar el tutor manualmente y revisar o ajustar los alumnos de cada grupo.</Info><div className="card-grid">{grupos.map(g=><article className="group-card-v6" key={g.id_grupo}><div><span>{g.periodo_nombre}</span><h3>{g.nombre}</h3><p>{g.carrera} · {g.alumnos} alumnos</p><Field label="Asignación manual de tutor"><select value={g.id_profesor||''} onChange={e=>cambiarTutorGrupo(g,e.target.value)}><option value="">Selecciona tutor…</option>{catalogos.profesores.filter(p=>p.tutor_estadia&&Number(p.id_carrera)===Number(g.id_carrera)).map(p=><option key={p.id_profesor} value={p.id_profesor}>{p.nombre} {p.apellido}</option>)}</select></Field><div className="action-row"><button className="secondary-btn" onClick={()=>verGrupoAdmin(g)}>Ver / administrar alumnos</button><button className="danger-btn" onClick={()=>deleteGrupoEstadia(g)}>Eliminar grupo</button></div></div></article>)}</div>{adminGroupDetail&&<Panel><Title e={adminGroupDetail.nombre} t={`Alumnos del grupo · ${adminGroupDetail.alumnos?.length||0}/6`}/><div className="manual-assign-row"><select value={adminAlumnoAdd} onChange={e=>setAdminAlumnoAdd(e.target.value)}><option value="">Agregar alumno de la misma carrera…</option>{adminAvailable.map(a=><option key={a.id_estudiante} value={a.id_estudiante}>{a.matricula} · {a.nombre} {a.apellido} · {a.grupo_escolar||'Sin grupo'}</option>)}</select><button className="primary-btn small" disabled={!adminAlumnoAdd||(adminGroupDetail.alumnos?.length||0)>=6} onClick={addAlumnoGrupo}>Agregar</button></div><div className="table-wrap"><table><thead><tr><th>Alumno</th><th>Matrícula</th><th>Estado estadía</th><th>Expediente</th><th></th></tr></thead><tbody>{(adminGroupDetail.alumnos||[]).map(a=><tr key={a.id_estudiante}><td><strong>{a.nombre} {a.apellido}</strong><small>{a.correo}</small></td><td>{a.matricula}</td><td><Status v={a.estado_estadia||'Pendiente de registro'}/></td><td>{a.expediente_folio||'—'}</td><td><button className="danger-btn" onClick={()=>removeAlumnoGrupo(a)}>Retirar</button></td></tr>)}</tbody></table></div></Panel>}</section>}

  {tab==='talleres'&&role===1&&<section className="two-col"><Panel><Title e="TALLER = ENTREGA" t={editTaller?'Editar taller':'Nuevo taller'}/><form className="form-grid" onSubmit={saveTaller}>{[['Periodo','id_periodo'],['Nombre','nombre']].map(([l,k])=><Field label={l} key={k}>{k==='id_periodo'?<select value={(editTaller||tallerForm)[k]||''} onChange={e=>editTaller?setEditTaller({...editTaller,[k]:e.target.value}):setTallerForm({...tallerForm,[k]:e.target.value})}><option value="">Selecciona…</option>{periodos.map(p=><option key={p.id_periodo} value={p.id_periodo}>{p.nombre}</option>)}</select>:<input value={(editTaller||tallerForm)[k]||''} onChange={e=>editTaller?setEditTaller({...editTaller,[k]:e.target.value}):setTallerForm({...tallerForm,[k]:e.target.value})}/>}</Field>)}<Field label="Entrega"><select value={(editTaller||tallerForm).numero_entrega||1} onChange={e=>editTaller?setEditTaller({...editTaller,numero_entrega:Number(e.target.value)}):setTallerForm({...tallerForm,numero_entrega:Number(e.target.value)})}><option value="1">1er entregable</option><option value="2">2do entregable</option><option value="3">3er entregable</option></select></Field><Field label="Modalidad"><select value={(editTaller||tallerForm).modalidad||'presencial'} onChange={e=>editTaller?setEditTaller({...editTaller,modalidad:e.target.value}):setTallerForm({...tallerForm,modalidad:e.target.value})}><option>presencial</option><option>virtual</option><option>hibrida</option></select></Field><Field label="Rúbrica"><select value={(editTaller||tallerForm).id_rubrica||''} onChange={e=>editTaller?setEditTaller({...editTaller,id_rubrica:e.target.value}):setTallerForm({...tallerForm,id_rubrica:e.target.value})}><option value="">Rúbrica universal</option>{rubricas.map(r=><option key={r.id_rubrica} value={r.id_rubrica}>{r.nombre}</option>)}</select></Field><Field label="Apertura"><input type="datetime-local" value={String((editTaller||tallerForm).fecha_apertura||'').slice(0,16)} onChange={e=>editTaller?setEditTaller({...editTaller,fecha_apertura:e.target.value}):setTallerForm({...tallerForm,fecha_apertura:e.target.value})}/></Field><Field label="Cierre"><input type="datetime-local" value={String((editTaller||tallerForm).fecha_cierre||'').slice(0,16)} onChange={e=>editTaller?setEditTaller({...editTaller,fecha_cierre:e.target.value}):setTallerForm({...tallerForm,fecha_cierre:e.target.value})}/></Field><Field label="Ubicación / enlace" full><input value={(editTaller||tallerForm).ubicacion||''} onChange={e=>editTaller?setEditTaller({...editTaller,ubicacion:e.target.value}):setTallerForm({...tallerForm,ubicacion:e.target.value})}/></Field><Field label="Descripción" full><textarea value={(editTaller||tallerForm).descripcion||''} onChange={e=>editTaller?setEditTaller({...editTaller,descripcion:e.target.value}):setTallerForm({...tallerForm,descripcion:e.target.value})}/></Field><button className="primary-btn">{editTaller?'Guardar cambios':'Crear taller'}</button>{editTaller&&<button type="button" className="secondary-btn" onClick={()=>setEditTaller(null)}>Cancelar</button>}</form></Panel><Panel><Title e="CALENDARIO" t="Talleres configurados"/><div className="list-stack">{talleres.map(t=><div className="list-card" key={t.id_taller}><div><strong>{t.nombre}</strong><span>{t.periodo_nombre} · Entrega {t.numero_entrega||'—'} · cierre {dt(t.fecha_cierre||t.fecha_hora)}</span></div><div className="action-row"><button className="secondary-btn" onClick={()=>setEditTaller({...t})}>Editar</button><button className="danger-btn" onClick={()=>deleteTaller(t)}>Eliminar</button></div></div>)}</div></Panel></section>}

  {tab==='rubricas'&&role===1&&<section className="two-col"><Panel><Title e="RÚBRICA UNIVERSAL" t="Crear versión"/><form className="form-grid" onSubmit={saveRubrica}><Field label="Nombre" full><input value={rubricaForm.nombre} onChange={e=>setRubricaForm({...rubricaForm,nombre:e.target.value})}/></Field><Field label="Descripción" full><textarea value={rubricaForm.descripcion} onChange={e=>setRubricaForm({...rubricaForm,descripcion:e.target.value})}/></Field><Field label="Criterio" full><input value={rubricaForm.criterios[0].criterio} onChange={e=>setRubricaForm({...rubricaForm,criterios:[{...rubricaForm.criterios[0],criterio:e.target.value}]})}/></Field><button className="primary-btn">Guardar rúbrica</button></form><div className="list-stack compact">{rubricas.map(r=><div className="list-card" key={r.id_rubrica}><div><strong>{r.nombre}</strong><span>{r.descripcion||'Rúbrica institucional'}</span></div></div>)}</div></Panel><Panel><Title e="ESCALA CONFIGURABLE" t="SA · DE · AU"/><div className="score-grid"><Field label="SA"><input type="number" step="0.1" value={escala.valor_sa} onChange={e=>setEscala({...escala,valor_sa:e.target.value})}/></Field><Field label="DE"><input type="number" step="0.1" value={escala.valor_de} onChange={e=>setEscala({...escala,valor_de:e.target.value})}/></Field><Field label="AU"><input type="number" step="0.1" value={escala.valor_au} onChange={e=>setEscala({...escala,valor_au:e.target.value})}/></Field></div><button className="primary-btn" onClick={saveEscala}>Guardar escala</button></Panel></section>}

  {tab==='mis-grupos'&&role===4&&<section><Title e="TUTORÍA" t="Mis grupos asignados"/><div className="card-grid">{misGrupos.map(g=><button className="group-card-v6 selectable" key={g.id_grupo} onClick={()=>abrirGrupoProfesor(g)}><span>{g.periodo_nombre}</span><h3>{g.nombre}</h3><p>{g.carrera} · Generación {g.generacion||'—'}</p><strong>{g.total_alumnos} alumnos</strong></button>)}</div>{grupoDetalle&&<Panel><Title e={grupoDetalle.grupo.nombre} t="Alumnos del grupo"/><div className="table-wrap"><table><thead><tr><th>Alumno</th><th>Empresa</th><th>Horario</th><th>Proyecto</th><th>Promedio</th><th>Información</th><th>Memoria final</th></tr></thead><tbody>{grupoDetalle.alumnos.map(a=><tr key={a.id_estudiante}><td><strong>{a.nombre} {a.apellido}</strong><small>{a.matricula} · {a.correo}</small></td><td>{a.empresa_razon_social||'Pendiente'}</td><td>{a.horario_laboral||'—'}</td><td>{a.proyecto_titulo||'—'}</td><td>{a.promedio_estadia||'—'}</td><td><button className="secondary-btn" onClick={()=>setSelectedProfesorAlumno(a)}>Ver alumno</button></td><td>{a.memoria_final_habilitada?<Status v={a.memoria_final_ruta?'PDF recibido':'Habilitada'}/>:<button className="secondary-btn" onClick={()=>habilitarMemoria(a)}>Marcar terminada</button>}</td></tr>)}</tbody></table></div></Panel>}</section>}

  {tab==='revisiones'&&role===4&&<section><Title e="RETROALIMENTACIÓN" t="Avances por revisar"/><div className="toolbar"><input placeholder="Buscar alumno, matrícula o proyecto…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="table-wrap"><table><thead><tr><th>Alumno</th><th>Grupo</th><th>Entrega</th><th>Trabajo</th><th>Calificación</th><th></th></tr></thead><tbody>{entregasProfesor.filter(e=>`${e.nombre} ${e.apellido} ${e.matricula}`.toLowerCase().includes(search.toLowerCase())).map(e=><tr key={e.id_entrega}><td><strong>{e.nombre} {e.apellido}</strong><small>{e.matricula}</small></td><td>{e.grupo_nombre}</td><td>{e.titulo}</td><td>{e.enlace_google_docs?<a href={e.enlace_google_docs} target="_blank" rel="noreferrer">Abrir Google Docs</a>:e.ruta_archivo?<a href={buildFileUrl(e.ruta_archivo)} target="_blank" rel="noreferrer">Abrir archivo</a>:'—'}{e.comentario_estudiante&&<small>Nota: {e.comentario_estudiante}</small>}</td><td>{e.nivel?`${e.nivel} · ${e.calificacion}`:'—'}</td><td><button className="primary-btn small" onClick={()=>revisar(e)}>Evaluar / notas</button></td></tr>)}</tbody></table></div></section>}

  {tab==='alumnos'&&role===6&&<section><Title e="SERVICIOS ESCOLARES" t="Todos los alumnos"/><div className="filter-grid"><input placeholder="Buscar nombre o matrícula…" value={search} onChange={e=>setSearch(e.target.value)}/><select value={carreraFiltro} onChange={e=>setCarreraFiltro(e.target.value)}><option value="">Todas las carreras</option>{[...new Set(alumnos.map(a=>a.carrera_catalogo||a.carrera).filter(Boolean))].map(c=><option key={c}>{c}</option>)}</select><select value={grupoFiltro} onChange={e=>setGrupoFiltro(e.target.value)}><option value="">Todos los grupos</option>{[...new Set(alumnos.map(a=>a.grupo_escolar).filter(Boolean))].map(g=><option key={g}>{g}</option>)}</select></div>{Object.entries(alumnos.filter(a=>(!carreraFiltro||(a.carrera_catalogo||a.carrera)===carreraFiltro)&&(!grupoFiltro||a.grupo_escolar===grupoFiltro)&&`${a.nombre} ${a.apellido} ${a.matricula}`.toLowerCase().includes(search.toLowerCase())).reduce((acc,a)=>{const k=a.grupo_escolar||'Sin grupo';(acc[k]??=[]).push(a);return acc},{})).map(([grupo,items])=><Panel key={grupo}><Title e={items[0]?.carrera_catalogo||items[0]?.carrera||'Carrera'} t={`${grupo} · ${items.length} alumnos`}/><div className="table-wrap"><table><thead><tr><th>Alumno</th><th>Matrícula</th><th>Correo</th><th>Teléfono</th><th>Cuatrimestre</th><th>Estado</th><th></th></tr></thead><tbody>{items.map(a=><tr key={a.id_estudiante}><td><strong>{a.nombre} {a.apellido}</strong></td><td>{a.matricula}</td><td>{a.correo}</td><td>{a.telefono||'—'}</td><td>{a.semestre||'—'}</td><td><Status v={a.estado_usuario}/></td><td><button className="secondary-btn" onClick={()=>verAlumnoCompleto(a)}>Ver información</button></td></tr>)}</tbody></table></div></Panel>)}</section>}

  {tab==='seguros'&&[1,6].includes(role)&&<section><Title e={role===6?'REVISIÓN INSTITUCIONAL':'CONTROL DE SEGURO'} t="Seguro facultativo"/><div className="metric-grid insurance-metrics"><Metric l="Alumnos en estadía" v={seguros.length}/><Metric l="En revisión" v={seguros.filter(x=>x.estado==='en_revision'||x.estado==='pendiente').length}/><Metric l="Validados" v={seguros.filter(x=>x.estado==='validado').length}/><Metric l="Sin registrar" v={seguros.filter(x=>x.estado==='sin_registrar').length}/></div><div className="toolbar"><input placeholder="Buscar alumno, matrícula, grupo, empresa…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="table-wrap"><table><thead><tr><th>Alumno</th><th>Grupo</th><th>Periodo</th><th>Empresa / proyecto</th><th>Estado</th><th>Seguro</th><th>Acciones</th></tr></thead><tbody>{seguros.filter(s=>`${s.nombre} ${s.apellido} ${s.matricula} ${s.grupo_nombre} ${s.empresa_razon_social}`.toLowerCase().includes(search.toLowerCase())).map(s=><tr key={s.id_estadia}><td><strong>{s.nombre} {s.apellido}</strong><small>{s.matricula}</small></td><td>{s.grupo_nombre||'—'}</td><td>{s.periodo_nombre}</td><td>{s.empresa_razon_social||'Pendiente'}<small>{s.proyecto_titulo||'Proyecto pendiente'}</small></td><td><Status v={s.estado}/></td><td>{s.id_seguro?<button className="secondary-btn" onClick={()=>setSelectedSeguro(s)}>Ver información</button>:'Sin registro'}</td><td className="action-row">{role===6&&s.id_seguro&&['en_revision','pendiente','requiere_correccion'].includes(s.estado)&&<><button className="success-btn" onClick={()=>validarSeguro(s,'validado')}>Aceptar</button><button className="warning-btn" onClick={()=>validarSeguro(s,'requiere_correccion')}>Corregir</button><button className="danger-btn" onClick={()=>validarSeguro(s,'rechazado')}>Rechazar</button></>}{role===1&&<span className="muted">Consulta</span>}</td></tr>)}</tbody></table></div></section>}

  {tab==='expedientes'&&[1,6].includes(role)&&<section><Title e="EXPEDIENTE DIGITAL" t="Expedientes de estadía"/><div className="expedient-grid">{expedientes.map(e=><article className="expedient-card" key={e.id_expediente}><span>{e.folio}</span><h3>{e.nombre} {e.apellido}</h3><p>{e.matricula} · {e.grupo_nombre}</p><dl><div><dt>Empresa</dt><dd>{e.empresa_razon_social||'—'}</dd></div><div><dt>Proyecto</dt><dd>{e.proyecto_titulo}</dd></div><div><dt>Seguro</dt><dd>{e.seguro_estado||'Sin registrar'}</dd></div></dl><div className="progress-bar"><span style={{width:`${e.porcentaje_completo||0}%`}}/></div><small>El expediente conserva la memoria técnica final una vez autorizada por el profesor.</small></article>)}</div></section>}

  {tab==='perfil'&&[4,6].includes(role)&&<section className="profile-wrap"><Panel><Title e="CUENTA" t="Mi perfil"/><form className="form-grid" onSubmit={savePerfil}><Field label="Nombre"><input value={perfil.nombre||''} onChange={e=>setPerfil({...perfil,nombre:e.target.value})}/></Field><Field label="Apellido"><input value={perfil.apellido||''} onChange={e=>setPerfil({...perfil,apellido:e.target.value})}/></Field><Field label="Teléfono"><input value={perfil.telefono||''} onChange={e=>setPerfil({...perfil,telefono:e.target.value})}/></Field><Field label="Correo"><input value={perfil.correo||''} disabled/></Field><Field label="Nueva contraseña" full><input type="password" value={perfil.nueva_password||''} onChange={e=>setPerfil({...perfil,nueva_password:e.target.value})} placeholder="Déjala vacía para conservarla"/></Field><button className="primary-btn">Actualizar perfil</button></form></Panel></section>}

  {tab==='mi-estadia'&&role===2&&<section><div className="journey-banner"><div><span>MI ESTADÍA</span><h2>{contexto?.grupo_nombre||'Pendiente de asignación'}</h2><p>{contexto?`${contexto.periodo_nombre} · Tutor ${contexto.profesor_nombre}`:'El administrador debe asignarte a un grupo de estadía.'}</p></div></div>{contexto&&<Panel><Title e="EMPRESA Y PROYECTO" t="Información de estadía"/><form className="form-grid" onSubmit={saveEstadia}><Field label="Nombre de la empresa" full><input value={estadiaForm.empresa_razon_social} onChange={e=>setEstadiaForm({...estadiaForm,empresa_razon_social:e.target.value})} required/></Field><Field label="Responsable"><input value={estadiaForm.responsable_nombre} onChange={e=>setEstadiaForm({...estadiaForm,responsable_nombre:e.target.value})} required/></Field><Field label="Cargo"><input value={estadiaForm.responsable_cargo} onChange={e=>setEstadiaForm({...estadiaForm,responsable_cargo:e.target.value})}/></Field><Field label="Correo responsable"><input value={estadiaForm.responsable_correo} onChange={e=>setEstadiaForm({...estadiaForm,responsable_correo:e.target.value})}/></Field><Field label="Teléfono responsable"><input value={estadiaForm.responsable_telefono} onChange={e=>setEstadiaForm({...estadiaForm,responsable_telefono:e.target.value})}/></Field><div className="field full"><span>Horario laboral</span><div className="schedule-picker"><div className="weekday-grid">{DIAS.map(dia=><button type="button" key={dia} className={horarioDias.includes(dia)?'weekday active':'weekday'} onClick={()=>setHorarioDias(ds=>ds.includes(dia)?ds.filter(x=>x!==dia):[...ds,dia])}>{dia.slice(0,3)}</button>)}</div><div className="time-grid"><label><span>Entrada</span><input type="time" value={horarioInicio} onChange={e=>setHorarioInicio(e.target.value)}/></label><label><span>Salida</span><input type="time" value={horarioFin} onChange={e=>setHorarioFin(e.target.value)}/></label></div><small>{horarioDias.length?`${horarioDias.join(', ')} · ${horarioInicio} a ${horarioFin}`:'Selecciona los días laborales'}</small></div></div><Field label="Proyecto" full><input value={estadiaForm.proyecto_titulo} onChange={e=>setEstadiaForm({...estadiaForm,proyecto_titulo:e.target.value})} required/></Field><Field label="Problemática" full><textarea value={estadiaForm.proyecto_problematica} onChange={e=>setEstadiaForm({...estadiaForm,proyecto_problematica:e.target.value})}/></Field><Field label="Objetivo general" full><textarea value={estadiaForm.proyecto_objetivo_general} onChange={e=>setEstadiaForm({...estadiaForm,proyecto_objetivo_general:e.target.value})}/></Field><Field label="Actividades" full><textarea value={estadiaForm.proyecto_actividades} onChange={e=>setEstadiaForm({...estadiaForm,proyecto_actividades:e.target.value})}/></Field><button className="primary-btn">Guardar información</button></form></Panel>}</section>}

  {tab==='avances'&&role===2&&<section><Title e="TALLERES Y ENTREGAS" t="Mis entregas"/><div className="advance-grid">{fechas.map(f=>{const last=entregas.filter(e=>Number(e.id_fecha_avance)===Number(f.id_fecha_avance))[0];const closed=new Date()>new Date(f.fecha_limite);return <article className="advance-card" key={f.id_fecha_avance}><span>ENTREGA {f.numero_avance}</span><h3>{f.titulo}</h3><p>Cierre: {dt(f.fecha_limite)}</p>{last&&<><Status v={last.estado}/>{last.enlace_google_docs&&<a href={last.enlace_google_docs} target="_blank" rel="noreferrer">Abrir trabajo</a>}{last.comentario_estudiante&&<p><b>Tu nota:</b> {last.comentario_estudiante}</p>}{last.revision_observaciones&&<p><b>Profesor:</b> {last.revision_observaciones}</p>}{last.nivel&&<strong>{last.nivel} · {last.calificacion}</strong>}</>}<button className="primary-btn" disabled={closed} onClick={()=>entregarEnlace(f)}>{closed?'Entrega cerrada':last?'Actualizar entrega':'Compartir Google Docs'}</button></article>})}</div>{miEstadia&&<Panel><Title e="MEMORIA TÉCNICA" t="Versión final en PDF"/><p className="muted">Cuando tu profesor indique que está terminada, sube el PDF con la nomenclatura <b>grupo_nombre.pdf</b>. El sistema valida el nombre del archivo.</p><label className={`upload-btn ${!miEstadia.memoria_final_habilitada?'disabled':''}`}>{miEstadia.memoria_final_habilitada?'Seleccionar PDF final':'Esperando aprobación del profesor'}<input type="file" disabled={!miEstadia.memoria_final_habilitada} accept="application/pdf,.pdf" onChange={e=>memoriaFinal(e.target.files[0])}/></label>{miEstadia.memoria_final_ruta&&<a href={buildFileUrl(miEstadia.memoria_final_ruta)} target="_blank" rel="noreferrer">Ver memoria final</a>}</Panel>}</section>}

  {tab==='seguro'&&role===2&&<section className="profile-wrap"><Panel><Title e="SEGURO FACULTATIVO" t={miEstadia?.seguro_estado==='validado'?'Seguro validado':'Enviar a revisión'}/>{miEstadia?.seguro_estado==='validado'?<div className="insurance-approved"><div className="approved-head"><span>✓</span><div><strong>Seguro facultativo validado</strong><small>Servicios Escolares revisó y aceptó la información.</small></div></div><div className="detail-grid"><Detail l="Número de seguro" v={miEstadia.numero_seguro}/><Detail l="Folio de pago" v={miEstadia.folio_pago}/><Detail l="Fecha de pago" v={d(miEstadia.fecha_pago)}/><Detail l="Vigencia" v={`${d(miEstadia.vigencia_inicio)} – ${d(miEstadia.vigencia_fin)}`}/><Detail l="Monto" v={miEstadia.monto?`$${miEstadia.monto}`:'—'}/><Detail l="Documento" v={miEstadia.seguro_archivo||'Comprobante registrado'}/></div>{miEstadia.ruta_comprobante&&<a className="secondary-btn" href={buildFileUrl(miEstadia.ruta_comprobante)} target="_blank" rel="noreferrer">Abrir comprobante</a>}</div>:<><p className="muted">Completa la información y envía el comprobante. Servicios Escolares será responsable de aceptarlo, solicitar una corrección o rechazarlo.</p><form className="form-grid" onSubmit={saveSeguro}><Field label="Número de seguro"><input value={seguroForm.numero_seguro} onChange={e=>setSeguroForm({...seguroForm,numero_seguro:e.target.value})}/></Field><Field label="Folio de pago"><input value={seguroForm.folio_pago} onChange={e=>setSeguroForm({...seguroForm,folio_pago:e.target.value})}/></Field><Field label="Fecha de pago"><input type="date" value={seguroForm.fecha_pago} onChange={e=>setSeguroForm({...seguroForm,fecha_pago:e.target.value})}/></Field><Field label="Monto"><input type="number" step="0.01" value={seguroForm.monto} onChange={e=>setSeguroForm({...seguroForm,monto:e.target.value})}/></Field><Field label="Vigencia inicio"><input type="date" value={seguroForm.vigencia_inicio} onChange={e=>setSeguroForm({...seguroForm,vigencia_inicio:e.target.value})}/></Field><Field label="Vigencia fin"><input type="date" value={seguroForm.vigencia_fin} onChange={e=>setSeguroForm({...seguroForm,vigencia_fin:e.target.value})}/></Field><Field label="Comprobante" full><input type="file" accept="application/pdf,image/*" onChange={e=>setSeguroForm({...seguroForm,archivo:e.target.files[0]})}/></Field><button className="primary-btn">Enviar a Servicios Escolares</button></form>{miEstadia?.seguro_estado&&<div className="insurance-status"><Status v={miEstadia.seguro_estado}/>{miEstadia.seguro_observaciones&&<p>{miEstadia.seguro_observaciones}</p>}</div>}</>}</Panel></section>}

  {tab==='guias'&&[2,4].includes(role)&&<section><Title e="DOCUMENTACIÓN" t="Guías de estadía"/><div className="list-stack">{guias.map(g=><div className="list-card" key={g.id_guia}><div><strong>{g.nombre}</strong><span>Versión {g.version}</span></div><a className="secondary-btn" href={buildFileUrl(g.ruta_archivo)} target="_blank" rel="noreferrer">Abrir</a></div>)}</div></section>}
  {selectedProfesorAlumno&&<div className="internship-modal-backdrop" onClick={()=>setSelectedProfesorAlumno(null)}><div className="internship-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSelectedProfesorAlumno(null)}>×</button><Title e={`${selectedProfesorAlumno.matricula} · ${grupoDetalle?.grupo?.nombre||''}`} t={`${selectedProfesorAlumno.nombre} ${selectedProfesorAlumno.apellido}`}/><div className="modal-section"><h3>Alumno</h3><div className="detail-grid"><Detail l="Correo" v={selectedProfesorAlumno.correo}/><Detail l="Teléfono" v={selectedProfesorAlumno.telefono}/><Detail l="Carrera" v={selectedProfesorAlumno.carrera}/><Detail l="Estado de estadía" v={selectedProfesorAlumno.estado}/></div></div><div className="modal-section"><h3>Empresa</h3><div className="detail-grid"><Detail l="Empresa" v={selectedProfesorAlumno.empresa_razon_social}/><Detail l="Responsable" v={selectedProfesorAlumno.responsable_nombre}/><Detail l="Cargo" v={selectedProfesorAlumno.responsable_cargo}/><Detail l="Correo responsable" v={selectedProfesorAlumno.responsable_correo}/><Detail l="Teléfono responsable" v={selectedProfesorAlumno.responsable_telefono}/><Detail l="Horario laboral" v={selectedProfesorAlumno.horario_laboral}/></div></div><div className="modal-section"><h3>Proyecto de estadía</h3><div className="detail-grid"><Detail l="Proyecto" v={selectedProfesorAlumno.proyecto_titulo}/><Detail l="Periodo" v={`${d(selectedProfesorAlumno.fecha_inicio)} – ${d(selectedProfesorAlumno.fecha_fin)}`}/></div><p><b>Problemática:</b> {selectedProfesorAlumno.proyecto_problematica||'—'}</p><p><b>Objetivo general:</b> {selectedProfesorAlumno.proyecto_objetivo_general||'—'}</p><p><b>Actividades:</b> {selectedProfesorAlumno.proyecto_actividades||'—'}</p></div></div></div>}
  {selectedSeguro&&<div className="internship-modal-backdrop" onClick={()=>setSelectedSeguro(null)}><div className="internship-modal insurance-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSelectedSeguro(null)}>×</button><Title e={`${selectedSeguro.matricula} · ${selectedSeguro.grupo_nombre}`} t="Información del seguro facultativo"/><div className="detail-grid"><Detail l="Alumno" v={`${selectedSeguro.nombre} ${selectedSeguro.apellido}`}/><Detail l="Estado" v={String(selectedSeguro.estado||'').replaceAll('_',' ')}/><Detail l="Número de seguro" v={selectedSeguro.numero_seguro}/><Detail l="Folio de pago" v={selectedSeguro.folio_pago}/><Detail l="Fecha de pago" v={d(selectedSeguro.fecha_pago)}/><Detail l="Monto" v={selectedSeguro.monto?`$${selectedSeguro.monto}`:'—'}/><Detail l="Vigencia inicio" v={d(selectedSeguro.vigencia_inicio)}/><Detail l="Vigencia fin" v={d(selectedSeguro.vigencia_fin)}/></div>{selectedSeguro.observaciones&&<div className="modal-section"><h3>Observaciones</h3><p>{selectedSeguro.observaciones}</p></div>}{selectedSeguro.ruta_comprobante&&<div className="modal-section"><a className="primary-btn" href={buildFileUrl(selectedSeguro.ruta_comprobante)} target="_blank" rel="noreferrer">Abrir comprobante</a></div>}</div></div>}
  {selectedAlumno&&<div className="internship-modal-backdrop" onClick={()=>setSelectedAlumno(null)}><div className="internship-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSelectedAlumno(null)}>×</button><Title e={`${selectedAlumno.alumno.matricula} · ${selectedAlumno.alumno.grupo_escolar||'Sin grupo'}`} t={`${selectedAlumno.alumno.nombre} ${selectedAlumno.alumno.apellido}`}/><div className="detail-grid">{[['Carrera',selectedAlumno.alumno.carrera_catalogo||selectedAlumno.alumno.carrera],['Generación',selectedAlumno.alumno.generacion],['Correo',selectedAlumno.alumno.correo],['Teléfono',selectedAlumno.alumno.telefono],['Cuatrimestre',selectedAlumno.alumno.semestre],['Estado',selectedAlumno.alumno.estado_usuario],['Título profesional',selectedAlumno.alumno.titulo_profesional],['Idiomas',selectedAlumno.alumno.idiomas],['Disponibilidad',selectedAlumno.alumno.disponibilidad],['Modalidad',selectedAlumno.alumno.modalidad_preferida],['Ciudad',selectedAlumno.alumno.ciudad],['LinkedIn',selectedAlumno.alumno.linkedin],['GitHub',selectedAlumno.alumno.github],['Portafolio',selectedAlumno.alumno.portafolio],['Competencias',selectedAlumno.alumno.competencias],['Biografía',selectedAlumno.alumno.biografia]].map(([l,v])=><div className="detail-item" key={l}><span>{l}</span><strong>{v||'—'}</strong></div>)}</div><div className="modal-section"><h3>Proyectos</h3>{selectedAlumno.proyectos?.length?selectedAlumno.proyectos.map(p=><p key={p.id_proyecto}><b>{p.titulo}</b> · {p.estado} · {p.tecnologias||'Sin tecnologías registradas'}</p>):<p>Sin proyectos.</p>}</div><div className="modal-section"><h3>Habilidades blandas</h3><p>{selectedAlumno.softSkills?`Puntaje total: ${selectedAlumno.softSkills.puntaje_total}`:'Sin evaluación registrada.'}</p></div><div className="modal-section"><h3>Estadía</h3><p>{selectedAlumno.estadia?`${selectedAlumno.estadia.periodo_nombre} · ${selectedAlumno.estadia.grupo_estadia} · Tutor ${selectedAlumno.estadia.profesor_nombre}`:'El alumno no está actualmente en estadía.'}</p></div></div></div>}
  </main></div>
}

const Panel=({children})=><div className="panel">{children}</div>;
const Title=({e,t})=><div className="section-title"><div><span>{e}</span><h2>{t}</h2></div></div>;
const Field=({label,children,full})=><label className={`field ${full?'full':''}`}><span>{label}</span>{children}</label>;
const Metric=({l,v})=><div className="metric-card"><div><strong>{v}</strong><small>{l}</small></div></div>;
const Info=({children})=><div className="info-box"><AppIcon name="info"/><p>{children}</p></div>;
const Detail=({l,v})=><div className="detail-item"><span>{l}</span><strong>{v||'—'}</strong></div>;
const BarChart=({items=[]})=>{const max=Math.max(1,...items.map(x=>Number(x.total||0)));return <div className="mini-chart">{items.length?items.map((x,i)=><div className="mini-chart-row" key={`${x.etiqueta}-${i}`}><div className="mini-chart-label"><span>{x.etiqueta}</span><strong>{x.total}</strong></div><div className="mini-chart-track"><span style={{width:`${Math.max(4,(Number(x.total||0)/max)*100)}%`}}/></div></div>):<p className="muted">Todavía no hay datos para graficar.</p>}</div>};
function Status({v}){const x=String(v||'').toLowerCase();return <span className={`status-chip ${['activo','validado','aprobado','completo'].some(y=>x.includes(y))?'good':['pendiente','revision','correccion','incompleto'].some(y=>x.includes(y))?'warn':'neutral'}`}>{String(v||'—').replaceAll('_',' ')}</span>}
